def compress(s):
    if not s:
        return ''
    result = ''
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            result += current + (str(count) if count > 1 else '')
            current = ch
            count = 1
