solution:
def merge_inventories(store_a, store_b):
    merged = {}
    for store in (store_a, store_b):
        for item, info in store.items():
            if info['qty'] <= 0:
                continue
            if item in merged:
                merged[item]['qty'] += info['qty']
                merged[item]['price'] = min(merged[item]['price'], info['price'])
            else:
                merged[item] = {'qty': info['qty'], 'price': info['price']}
    return {item: merged[item] for item in sorted(merged)}

