solution:
def longest_streak(steps, target):
    best_len, best_start = 0, -1
    cur_len, cur_start = 0, 0
    for i, value in enumerate(steps):
        if value >= target:
            if cur_len == 0:
                cur_start = i
            cur_len += 1
            if cur_len > best_len:
                best_len, best_start = cur_len, cur_start
        else:
            cur_len = 0
    return (best_len, best_start)

