def top_passers(csv_text):
    lines = [line for line in csv_text.splitlines() if line.strip()]
    if not lines:
        return []
    passed = []
    for line in lines[1:]:
        parts = [p.strip() for p in line.split(',')]
        name = parts[0]
        marks = [int(m) for m in parts[1:]]
        if all(m >= 40 for m in marks):
            passed.append((-sum(marks), name))
    passed.sort()
