solution:
def password_issues(pw):
    issues = []
    if len(pw) < 8:
        issues.append('length')
    if not any(ch.isupper() for ch in pw):
        issues.append('upper')
    if not any(ch.islower() for ch in pw):
        issues.append('lower')
    if not any(ch.isdigit() for ch in pw):
        issues.append('digit')
    if not any(ch in '!@#$%&*' for ch in pw):
        issues.append('special')
    if ' ' in pw:
        issues.append('space')
    return issues

