solution:
def settle_balances(members, expenses):
    if not members:
        return {}
    paid = {name: 0 for name in members}
    total = 0
    for payer, amount in expenses:
        paid[payer] += amount
        total += amount
    share = total / len(members)
    result = {}
    for name in sorted(members):
        balance = round(paid[name] - share, 2)
        result[name] = balance + 0.0
    return result

