    pass

solution:
def league_table(results):
    points = {}
    diff = {}
    for line in results:
        home, score, away = line.split()
        home_goals, away_goals = [int(x) for x in score.split('-')]
        for team in (home, away):
            points.setdefault(team, 0)
            diff.setdefault(team, 0)
        diff[home] += home_goals - away_goals
        diff[away] += away_goals - home_goals
        if home_goals > away_goals:
            points[home] += 3
        elif home_goals < away_goals:
            points[away] += 3
        else:
            points[home] += 1
            points[away] += 1
    table = [(team, points[team], diff[team]) for team in points]
    table.sort(key=lambda row: (-row[1], -row[2], row[0]))
    return table
